#!/usr/bin/env python3
"""
Minimal agentic loop with Anthropic API, bash execution tool, and human confirmation.
"""

import os
import sys
import subprocess
import json
from typing import Dict, List, Optional
import anthropic

class BashTool:
    """Tool for executing bash commands with human confirmation."""

    def __init__(self, require_confirmation: bool = True):
        self.require_confirmation = require_confirmation

    def run(self, command: str) -> Dict[str, any]:
        """Execute a bash command after optional human confirmation."""
        if self.require_confirmation:
            print(f"\n🔧 Tool wants to execute command:")
            print(f"  $ {command}")
            response = input("Execute? (y/n): ").strip().lower()

            if response != 'y':
                return {
                    "status": "cancelled",
                    "output": "Command execution cancelled by user"
                }

        try:
            result = subprocess.run(
                command,
                shell=True,
                capture_output=True,
                text=True,
                timeout=30
            )

            return {
                "status": "success",
                "output": result.stdout,
                "error": result.stderr,
                "return_code": result.returncode
            }
        except subprocess.TimeoutExpired:
            return {
                "status": "error",
                "output": "",
                "error": "Command timed out after 30 seconds"
            }
        except Exception as e:
            return {
                "status": "error",
                "output": "",
                "error": str(e)
            }

class AgentLoop:
    """Minimal agentic loop using Anthropic API."""

    def __init__(self, api_key: str):
        self.client = anthropic.Anthropic(api_key=api_key)
        self.bash_tool = BashTool()
        self.conversation_history = []

        # Tool definition for Claude
        self.tools = [
            {
                "name": "run_bash",
                "description": "Execute a bash command",
                "input_schema": {
                    "type": "object",
                    "properties": {
                        "command": {
                            "type": "string",
                            "description": "The bash command to execute"
                        }
                    },
                    "required": ["command"]
                }
            }
        ]

    def process_tool_call(self, tool_call: Dict) -> Dict:
        """Process a tool call from Claude."""
        if tool_call["name"] == "run_bash":
            command = tool_call["input"]["command"]
            return self.bash_tool.run(command)
        else:
            return {
                "status": "error",
                "output": f"Unknown tool: {tool_call['name']}"
            }

    def run(self, initial_prompt: str, max_iterations: int = 10):
        """Run the agent loop."""
        print(f"\n🤖 Starting agent with prompt: {initial_prompt}\n")

        # Add initial user message
        self.conversation_history.append({
            "role": "user",
            "content": initial_prompt
        })

        for iteration in range(max_iterations):
            print(f"\n--- Iteration {iteration + 1} ---")

            # Get Claude's response
            response = self.client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=4096,
                temperature=0,
                tools=self.tools,
                messages=self.conversation_history
            )

            # Add assistant's response to history
            self.conversation_history.append({
                "role": "assistant",
                "content": response.content
            })

            # Check if Claude wants to use tools
            tool_calls = [block for block in response.content if block.type == "tool_use"]

            if not tool_calls:
                # No tools used, print final response
                text_blocks = [block for block in response.content if block.type == "text"]
                if text_blocks:
                    print(f"\n💬 Assistant: {text_blocks[0].text}")
                break

            # Process tool calls
            tool_results = []
            for tool_call in tool_calls:
                print(f"\n🔨 Claude wants to use tool: {tool_call.name}")
                result = self.process_tool_call(tool_call)

                tool_results.append({
                    "type": "tool_result",
                    "tool_use_id": tool_call.id,
                    "content": json.dumps(result)
                })

            # Add tool results to conversation
            self.conversation_history.append({
                "role": "user",
                "content": tool_results
            })

            # Print any text from Claude before tool use
            text_blocks = [block for block in response.content if block.type == "text"]
            if text_blocks:
                print(f"\n💬 Assistant: {text_blocks[0].text}")

        print("\n✅ Agent loop completed")

def main():
    # Get API key from environment or prompt user
    api_key = os.environ.get("ANTHROPIC_API_KEY")
    if not api_key:
        print("ANTHROPIC_API_KEY not found in environment.")
        api_key = input("Enter your Anthropic API key: ").strip()

    # Get task from user
    if len(sys.argv) > 1:
        task = " ".join(sys.argv[1:])
    else:
        task = input("Enter task for the agent: ").strip()

    if not task:
        print("No task provided. Exiting.")
        return

    # Create and run agent
    agent = AgentLoop(api_key)
    agent.run(task)

if __name__ == "__main__":
    main()

